INSERT INTO article_translations (article_id, lang, headline, summary, what_happened, why_it_matters, figures_dates, affected_entities, risks_uncertainty, grammar_checked, created_at, updated_at) VALUES
('sample_01', 'ka', '[ნიმუში] საქართველოს ეროვნულმა ბანკმა რეფინანსირების განაკვეთი უცვლელი დატოვა', 'ცენტრალურმა ბანკმა მთავარი განაკვეთი უცვლელი დატოვა და განაცხადა, რომ ინფლაცია სამიზნე ტრაექტორიას მიჰყვება.', 'საქართველოს ეროვნული ბანკის მონეტარული პოლიტიკის კომიტეტმა ბოლო სხდომაზე რეფინანსირების განაკვეთი უცვლელი დატოვა. კომიტეტის თქმით, წლიური ინფლაცია სამიზნე მაჩვენებელთან ახლოსაა, შიდა მოთხოვნა კი ზომიერად იზრდება.', 'ქართველი შინამეურნეობებისა და ბიზნესისთვის სესხის ღირებულება ჯერჯერობით იგივე რჩება. უცვლელი განაკვეთი იმასაც ნიშნავს, რომ პოლიტიკის შემქმნელები გაცვლითი კურსის ბოლოდროინდელ ცვლილებებზე რეაგირებას საჭიროდ არ თვლიან.', 'რეფინანსირების განაკვეთი: 8.0%
ინფლაცია: 3.4% წლიური ზრდა
შემდეგი სხდომა: 11 დეკემბერი', 'საქართველოს ეროვნული ბანკი, ქართული ბანკები, მსესხებლები', 'გადაწყვეტილება იმაზეა დამოკიდებული, შენარჩუნდება თუ არა ინფლაციის ტრაექტორია; ლარის მკვეთრმა გაუფასურებამ ან ენერგიის ფასების შოკმა შეიძლება შემდეგ სხდომამდე პროგნოზი შეცვალოს.', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-4 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-4 minutes')),
